#[energyml(
    package = "prodml",
    version = "2.0",
    xml_name = "Standing-BubblePoint",
    base = AbstractCorrelationViscosityBubblePointModel
)]
pub struct Standing_BubblePoint {
    #[energyml(elem, xml_name = "CustomPvtModelExtension")]
    pub custom_pvt_model_extension: Option<CustomPvtModelExtension>,

    #[energyml(elem, xml_name = "PvtModelParameterSet")]
    pub pvt_model_parameter_set: Option<PvtModelParameterSet>,

    /// The molecular weight of the fluid for the viscosity model.
    #[energyml(elem, xml_name = "MolecularWeight")]
    pub molecular_weight: Vec<energyml_eml_2_1::MolecularWeightMeasure>,

    /// The bubble point viscosity output from the bubble point viscosity model.
    #[energyml(elem, xml_name = "BubblePointOilViscosity")]
    pub bubble_point_oil_viscosity: Vec<energyml_eml_2_1::DynamicViscosityMeasure>,

    /// The dead oil viscosity input for the bubble point viscosity model.
    #[energyml(elem, xml_name = "DeadOilViscosity")]
    pub dead_oil_viscosity: Vec<energyml_eml_2_1::DynamicViscosityMeasure>,

    /// The solution gas oil ratio for the bubble point viscosity model.
    #[energyml(elem, xml_name = "SolutionGasOilRate")]
    pub solution_gas_oil_rate: Vec<energyml_eml_2_1::DimensionlessMeasure>,

}

