/// Delimiter definition for a table.
#[derive(Debug, Default, Clone, PartialEq, EnergymlObject)]
#[energyml(
    package = "prodml",
    version = "2.0",
    xml_name = "TableDelimiter"
)]
pub struct TableDelimiter {
    /// The ascii character which represents a column delimiter in each row of a table using this table format.
    #[energyml(attr, xml_name = "asciiCharacters", max_length = 64)]
    pub ascii_characters: String,

}

